package com.ethk3.novaonepro.strategyv2;
import java.io.*;
import java.util.*;
/** Five different causal computational graphs, trained end-to-end through exact permutation NLL.
 * F03 typed triple messages; F04 dilated TCN; F05 temporal attention; F06 selective SSM;
 * F07 graph GRU. Recurrent gradients use declared one-step truncation. */
public final class NeuralFamilyR26 implements TemporalModelR26,TrainingDiagnosticsR26 {
    private static final int W=4,H=8,PARAMETERS=4096;private final String family;private final int variant;private final double[] weights=new double[PARAMETERS],momentum=new double[PARAMETERS],recurrent=new double[40];private final int[][] ring=new int[H][10];private long t,lifetimeUpdates;private boolean completeUpdateHistory=true;private TrainingDiagnosticsR26.Step last;private double[] executionWeights=weights;private double lastLoss,gradientNorm;private final AutoDiffR26 tape=new AutoDiffR26(PARAMETERS);private int[] stateNodes;
    public NeuralFamilyR26(String family){this(family,0);}
    public NeuralFamilyR26(String family,int variant){if(variant<0||variant>2)throw new IllegalArgumentException("R26_GRAPH_VARIANT");this.variant=variant;if(!Arrays.asList("F03","F04","F05","F06","F07").contains(family))throw new IllegalArgumentException("R26_NEURAL_FAMILY");this.family=family;long seed=Long.parseLong(family.substring(1))*1234567+71;for(int i=0;i<PARAMETERS;i++){seed^=seed<<13;seed^=seed>>>7;seed^=seed<<17;weights[i]=(Math.floorMod(seed,10000)/10000.0-.5)*.2;}}
    private int w(int i){return tape.weight(i,executionWeights);}
    private int zero(){return tape.constant(0);}
    private int sum(int a,int b){return tape.add(a,b);}
    private int mul(int a,int b){return tape.multiply(a,b);}
    private int lag(int lag,int position){if(lag>=Math.min(t,H))return zero();return tape.constant((ring[(int)((t-1-lag)%H)][position]-5.5)/4.5);}
    private int[] embedding(int lag){int[] h=new int[W];if(lag>=Math.min(t,H)){for(int k=0;k<W;k++)h[k]=zero();return h;}for(int k=0;k<W;k++){int z=w(400+k);for(int p=0;p<10;p++){if(lag<Math.min(t,H)){int digit=ring[(int)((t-1-lag)%H)][p]-1;z=sum(z,w((p*10+digit)*W+k));}}h[k]=tape.tanh(z);}return h;}
    private int affine(int base,int[] h,int out){int z=w(base+W*W+out);for(int j=0;j<W;j++)z=sum(z,mul(w(base+out*W+j),h[j]));return z;}
    private int[] tcn(){int[][] x=new int[H][W];for(int i=0;i<H;i++)x[i]=embedding(H-1-i);for(int layer=0;layer<2;layer++){int[][] y=new int[H][W];int dilation=variant==0?1<<layer:variant==1?(layer==0?1:3):(layer==0?2:4),base=420+layer*52;for(int i=0;i<H;i++)for(int k=0;k<W;k++){int z=w(base+48+k);for(int lag=0;lag<3;lag++){int at=i-lag*dilation;if(at<0)continue;for(int j=0;j<W;j++)z=sum(z,mul(w(base+(k*3+lag)*W+j),x[at][j]));}y[i][k]=tape.tanh(sum(z,x[i][k]));}x=y;}return x[H-1];}
    private int[] attention(){int[] selected=new int[H];int valid=0;for(int lag=0;lag<Math.max(1,Math.min(t,H));lag++)if(variant==0||variant==1&&lag%2==0||variant==2&&(lag==0||lag==1||lag==3||lag==7))selected[valid++]=lag;int[][] x=new int[valid][W],v=new int[valid][W];int[] q=new int[W],energy=new int[valid];for(int i=0;i<valid;i++)x[i]=embedding(selected[i]);for(int j=0;j<W;j++)q[j]=affine(540,x[0],j);double maximum=-1e30;for(int i=0;i<valid;i++){int e=zero();for(int k=0;k<W;k++){e=sum(e,mul(q[k],affine(560,x[i],k)));v[i][k]=affine(580,x[i],k);}energy[i]=mul(e,tape.constant(.5));maximum=Math.max(maximum,tape.value(energy[i]));}
        int denominator=zero();int[] e=new int[valid];for(int i=0;i<valid;i++){e[i]=tape.exp(sum(energy[i],tape.constant(-maximum)));denominator=sum(denominator,e[i]);}int[] h=new int[W];for(int k=0;k<W;k++){h[k]=zero();for(int i=0;i<valid;i++)h[k]=sum(h[k],mul(tape.divide(e[i],denominator),v[i][k]));h[k]=tape.tanh(h[k]);}return h;}
    private int recurrentInput(int k){if(variant==0)return tape.constant(recurrent[k]);int z=zero();for(int j=0;j<W;j++)if(variant==1||j==k||j==(k+1)%W)z=sum(z,mul(w(950+k*W+j),tape.constant(recurrent[j])));return tape.tanh(z);}
    private boolean edge(int p,int q){return variant==0||variant==1&&(q==p||q==(p+1)%10||q==(p+9)%10)||variant==2&&(q==p||q==(p+3)%10||q==(p+7)%10);}
    private int[] ssm(){int[] x=embedding(0),h=new int[W];for(int k=0;k<W;k++){int a=tape.sigmoid(affine(610,x,k)),b=tape.tanh(affine(630,x,k));h[k]=sum(mul(a,recurrentInput(k)),mul(b,x[k]));}stateNodes=h;return h;}
    private int[][] graph(boolean hyper){int[][] x=new int[10][W],h=new int[10][W];for(int p=0;p<10;p++)for(int k=0;k<W;k++){int z=w(405+k);if(t>0){int digit=ring[(int)((t-1)%H)][p]-1;z=sum(z,w((p*10+digit)*W+k));}x[p][k]=tape.tanh(z);}
        stateNodes=new int[40];for(int p=0;p<10;p++){int[] message=new int[W];if(hyper){for(int k=0;k<W;k++){int z=x[p][k];for(int j=0;j<W;j++)z=sum(z,mul(w(660+k*W+j),mul(x[(p+(variant==2?2:1))%10][j],x[(p+(variant==0?2:variant==1?3:5))%10][j])));h[p][k]=tape.tanh(z);}}
            else{int denominator=zero();int[] edges=new int[10];double max=-1e30;for(int q=0;q<10;q++)if(edge(p,q))max=Math.max(max,executionWeights[700+p*10+q]);for(int q=0;q<10;q++){if(!edge(p,q))continue;edges[q]=tape.exp(sum(w(700+p*10+q),tape.constant(-max)));denominator=sum(denominator,edges[q]);}
                for(int k=0;k<W;k++){message[k]=zero();for(int q=0;q<10;q++){if(!edge(p,q))continue;int z=x[q][k];for(int j=0;j<W;j++)z=sum(z,mul(w(800+k*W+j),tape.constant(recurrent[q*W+j])));message[k]=sum(message[k],mul(tape.divide(edges[q],denominator),tape.tanh(z)));}}
                int[] reset=new int[W],update=new int[W];for(int k=0;k<W;k++){reset[k]=tape.sigmoid(sum(affine(830,message,k),mul(w(900+k),tape.constant(recurrent[p*W+k]))));update[k]=tape.sigmoid(sum(affine(850,message,k),mul(w(904+k),tape.constant(recurrent[p*W+k]))));}
                for(int k=0;k<W;k++){int z=affine(870,message,k);for(int j=0;j<W;j++)z=sum(z,mul(w(920+k*W+j),mul(reset[j],tape.constant(recurrent[p*W+j]))));h[p][k]=sum(mul(update[k],tape.constant(recurrent[p*W+k])),mul(sum(tape.constant(1),mul(tape.constant(-1),update[k])),tape.tanh(z)));}}
            for(int k=0;k<W;k++)stateNodes[p*W+k]=h[p][k];}return h;
    }
    private int[] forward(){return forward(weights);}
    private int[] forward(double[] parameters){executionWeights=parameters;try{return buildGraph();}finally{executionWeights=weights;}}
    private int[] buildGraph(){tape.reset();stateNodes=null;int[] h=null;int[][] graph=null;switch(family){case "F03":graph=graph(true);break;case "F04":h=tcn();break;case "F05":h=attention();break;case "F06":h=ssm();break;case "F07":graph=graph(false);break;default:throw new AssertionError();}int[] output=new int[100];for(int p=0;p<10;p++)for(int n=0;n<10;n++){int j=p*10+n,z=w(1500+j);for(int k=0;k<W;k++)z=sum(z,mul(w(1000+j*W+k),graph==null?h[k]:graph[p][k]));output[j]=z;}return output;}
    private double[][] table(int[] output){double[][] s=new double[10][10];for(int i=0;i<100;i++)s[i/10][i%10]=tape.value(output[i]);return s;}
    double objective(int[] draw){int[] out=forward(),target=new int[10];for(int p=0;p<10;p++)target[p]=draw[p]-1;double[][] s=table(out);return ExactPermutationR26.nll(s,target,ExactPermutationR26.infer(s,null));}
    public void resetTemporalContext(){t=0;last=null;for(int[] row:ring)java.util.Arrays.fill(row,0);java.util.Arrays.fill(recurrent,0);lastLoss=0;gradientNorm=0;tape.reset();}
    public TrainingDiagnosticsR26.Step lastTrainingStep(){return last;}
    public long completedTrainingUpdates(){return lifetimeUpdates;}
    public String optimizerProtocol(){return "MOMENTUM09_GRAD_CLIP5_STEP003_PARAM_CLIP6_V3_"+(completeUpdateHistory?"KNOWN_LIFETIME":"LEGACY_COUNTER_LOWER_BOUND");}
    private String inputHash(){StringBuilder input=new StringBuilder("NEURAL_FIXED_CAUSAL_INPUT_V3|").append(family).append('|').append(variant).append('|').append(t).append('|').append(lifetimeUpdates).append('|').append(completeUpdateHistory);for(int[] row:ring)for(int value:row)input.append('|').append(value);for(double value:recurrent)input.append('|').append(Double.toHexString(value));return PolicyIdentityR26.sha256(input.toString());}
    public int stateWidth(){return 3;}
    public void predict(float[][] p,float[] st){ExactPermutationR26.Result r=ExactPermutationR26.infer(table(forward()),null);for(int i=0;i<10;i++)for(int j=0;j<10;j++)p[i][j]=(float)r.marginal[i][j];st[0]=(float)Math.log1p(t);st[1]=(float)lastLoss;st[2]=(float)gradientNorm;}
    public void update(int[] draw){
        OnlineModelsSU2.requireDraw(draw);ExecutionBudgetR26.poll();if(t==Long.MAX_VALUE||lifetimeUpdates==Long.MAX_VALUE)throw new IllegalStateException("R26_NEURAL_UPDATE_CLOCK_CAPACITY");int[] out=forward();double[][] scores=table(out);ExactPermutationR26.Result distribution=ExactPermutationR26.infer(scores,null);double[] seed=new double[100];int[] target=new int[10];for(int p=0;p<10;p++){target[p]=draw[p]-1;for(int n=0;n<10;n++)seed[p*10+n]=distribution.marginal[p][n]-(draw[p]==n+1?1:0);}double before=ExactPermutationR26.nll(scores,target,distribution);double[] gradient=tape.backward(out,seed);double squared=0;for(double value:gradient)squared+=value*value;double norm=Math.sqrt(squared),scale=norm>5?5/norm:1,deltaSquared=0;
        double[] nextRecurrent=stateNodes==null?null:new double[stateNodes.length];if(nextRecurrent!=null)for(int i=0;i<nextRecurrent.length;i++)nextRecurrent[i]=tape.value(stateNodes[i]);double[] nextWeights=new double[PARAMETERS],nextMomentum=new double[PARAMETERS];for(int i=0;i<PARAMETERS;i++){nextMomentum[i]=.9*momentum[i]+.1*gradient[i]*scale;nextWeights[i]=Math.max(-6,Math.min(6,weights[i]-.03*nextMomentum[i]));double delta=nextWeights[i]-weights[i];deltaSquared+=delta*delta;}
        // Keep the complete pre-label ring and old recurrent state frozen while
        // evaluating the updated parameters. Commit the original forward state.
        double[][] afterScores=table(forward(nextWeights));double after=ExactPermutationR26.nll(afterScores,target,ExactPermutationR26.infer(afterScores,null));TrainingDiagnosticsR26.Step step=new TrainingDiagnosticsR26.Step(lifetimeUpdates+1,before,after,norm,Math.sqrt(deltaSquared),inputHash(),"EXACT_PERMUTATION_JOINT_NLL_FIXED_PRE_LABEL_RING_AND_RECURRENT_STATE;DECLARED_ONE_STEP_TRUNCATED_RECURRENT_GRADIENT;DELTA=4096_WEIGHTS");ExecutionBudgetR26.poll();
        if(nextRecurrent!=null)System.arraycopy(nextRecurrent,0,recurrent,0,nextRecurrent.length);System.arraycopy(nextWeights,0,weights,0,PARAMETERS);System.arraycopy(nextMomentum,0,momentum,0,PARAMETERS);ring[(int)(t%H)]=draw.clone();t++;lifetimeUpdates++;lastLoss=before;gradientNorm=norm;last=step;
    }
    public void write(DataOutput o)throws IOException{o.writeInt(0x26220003);o.writeUTF(family);o.writeInt(variant);o.writeLong(t);o.writeDouble(lastLoss);o.writeDouble(gradientNorm);for(int[] row:ring)for(int n:row)o.writeInt(n);for(double[] a:new double[][]{weights,momentum,recurrent})for(double x:a)o.writeDouble(x);o.writeLong(lifetimeUpdates);o.writeBoolean(completeUpdateHistory);}
    public void read(DataInput in)throws IOException{
        int header=in.readInt();if((header!=0x26220002&&header!=0x26220003)||!family.equals(in.readUTF())||in.readInt()!=variant)throw new IOException("R26_NEURAL_ABI");long contextClock=in.readLong();double loss=in.readDouble(),norm=in.readDouble();if(contextClock<0||!Double.isFinite(loss)||!Double.isFinite(norm)||norm<0)throw new IOException("R26_NEURAL_STATE");int[][] history=new int[H][10];for(int[] row:history)for(int j=0;j<10;j++){row[j]=in.readInt();if(row[j]<0||row[j]>10)throw new IOException("R26_NEURAL_HISTORY");}
        for(int lag=0;lag<Math.min(contextClock,H);lag++)try{OnlineModelsSU2.requireDraw(history[(int)((contextClock-1-lag)%H)]);}catch(IllegalArgumentException bad){throw new IOException("R26_NEURAL_HISTORY_DRAW",bad);}
        double[] restoredWeights=new double[PARAMETERS],restoredMomentum=new double[PARAMETERS],restoredRecurrent=new double[40];for(double[] values:new double[][]{restoredWeights,restoredMomentum,restoredRecurrent})for(int i=0;i<values.length;i++){values[i]=in.readDouble();if(!Double.isFinite(values[i])||Math.abs(values[i])>1e8)throw new IOException("R26_NEURAL_PARAMETER");}
        long lifetime=contextClock;boolean complete=false;if(header==0x26220003){lifetime=in.readLong();int flag=in.readUnsignedByte();if(lifetime<contextClock||flag>1)throw new IOException("R26_NEURAL_LIFETIME");complete=flag==1;}
        for(int i=0;i<H;i++)System.arraycopy(history[i],0,ring[i],0,10);System.arraycopy(restoredWeights,0,weights,0,PARAMETERS);System.arraycopy(restoredMomentum,0,momentum,0,PARAMETERS);System.arraycopy(restoredRecurrent,0,recurrent,0,40);t=contextClock;lifetimeUpdates=lifetime;completeUpdateHistory=complete;lastLoss=loss;gradientNorm=norm;last=null;stateNodes=null;tape.reset();
    }
}
